#![allow(dead_code)]
#[path="../src/elf.rs"]mod elf;
use elf::*;
fn put(b:&mut[u8],at:usize,n:u32){b[at..at+4].copy_from_slice(&n.to_le_bytes());}
fn sample()->Vec<u8>{let mut b=vec![0;8196];b[..7].copy_from_slice(&[127,69,76,70,1,1,1]);b[16]=2;b[18]=3;put(&mut b,20,1);put(&mut b,24,BASE);put(&mut b,28,52);b[40]=52;b[42]=32;b[44]=2;for(p,off,addr,files,mem,flags)in[(52,4096,BASE,8,8,5),(84,8192,BASE+8192,4,8192,6)]{for(i,n)in[1,off,addr,0,files,mem,flags,4096].iter().enumerate(){put(&mut b,p+i*4,*n);}}b}
#[test]fn loads_segments_bss_and_permissions(){let b=sample();let p=parse(&b).unwrap();assert_eq!(p.count,2);assert_eq!(p.span,16384);assert!(p.permits(BASE,8,false,HEAP_BASE));assert!(!p.permits(BASE,1,true,HEAP_BASE));assert!(!p.permits(BASE+8,1,false,HEAP_BASE));assert!(!p.permits(BASE+4096,1,false,HEAP_BASE));assert!(p.permits(BASE+8192,8192,true,HEAP_BASE));assert!(p.permits(HEAP_BASE,32,true,HEAP_BASE+32));assert!(!p.permits(HEAP_BASE,33,false,HEAP_BASE+32));assert!(!p.permits(HEAP_BASE,1,false,HEAP_BASE));assert!(!p.permits(0x403fbfff,1,false,HEAP_BASE));assert!(p.permits(0x403fc000,16384,true,HEAP_BASE));assert!(!p.permits(u32::MAX-2,8,false,HEAP_BASE));}
#[test]fn rejects_overlap_dynamic_interpreter_bad_entry_and_overflows(){for(at,n)in[(52+24,7),(52,3),(52,2),(24,BASE+8192),(24,BASE+7+2),(84+8,BASE),(84+20,u32::MAX),(52+16,9),(52+4,u32::MAX),(52+28,3),(28,u32::MAX)]{let mut b=sample();put(&mut b,at,n);assert!(parse(&b).is_err(),"accepted change {at}/{n}");}}
#[test]fn truncations_and_arbitrary_bytes_do_not_panic(){let b=sample();for n in 0..b.len(){assert!(parse(&b[..n]).is_err());}let mut seed=12345u32;for _ in 0..5000{let mut b=sample();for _ in 0..8{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);let at=(seed as usize)%120;seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);b[at]=seed as u8;}let _=parse(&b);}}
#[test]fn region_boundaries_can_cross_only_with_matching_access(){let mut p=parse(&sample()).unwrap();p.segments[1].address=BASE+8;p.segments[1].memory_size=8;assert!(p.permits(BASE,16,false,HEAP_BASE));assert!(!p.permits(BASE,16,true,HEAP_BASE));assert!(!p.permits(BASE+8,9,true,HEAP_BASE));}
